import{_ as n,a0 as s,w as o,s as d,ao as a,I as t,x as l,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables","title":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables.md","filePath":"[post].md"}'),w={name:"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables.md"};function f(m,e,u,b,T,C){const p=s("Link");return o(),d("div",null,[e[32]||(e[32]=a(`<h1 id="rhcsa-系列-十一-使用-firewalld-和-iptables-來控制網絡流量" tabindex="-1">RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量 <a class="header-anchor" href="#rhcsa-系列-十一-使用-firewalld-和-iptables-來控制網絡流量" aria-label="Permalink to “RHCSA 系列（十一）: 使用 firewalld 和 iptables 來控制網絡流量”">​</a></h1><p>簡單來説，防火牆就是一個基於一系列預先定義的規則（例如流量包的目的地或來源，流量的類型等）的安全系統，它控制着一個網絡中的流入和流出流量。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Control-Network-Traffic-Using-Firewall.png" alt="使用 FirewallD 和 Iptables 來控制網絡流量"></p><p><em>RHCSA: 使用 FirewallD 和 Iptables 來控制網絡流量 – Part 11</em></p><p>在本文中，我們將回顧 firewalld 和 iptables 的基礎知識。前者是 RHEL 7 中的默認動態防火牆守護進程，而後者則是針對 Linux 的傳統的防火牆服務，大多數的系統和網絡管理員都非常熟悉它，並且在 RHEL 7 中也可以用。</p><h3 id="firewalld-和-iptables-的一個比較" tabindex="-1">FirewallD 和 Iptables 的一個比較 <a class="header-anchor" href="#firewalld-和-iptables-的一個比較" aria-label="Permalink to “FirewallD 和 Iptables 的一個比較”">​</a></h3><p>在後台， firewalld 和 iptables 服務都通過相同的接口來與內核中的 netfilter 框架相交流，這不足為奇，即它們都通過 iptables 命令來與 netfilter 交互。然而，與 iptables 服務相反， firewalld 可以在不丟失現有連接的情況下，在正常的系統操作期間更改設定。</p><p>在默認情況下， firewalld 應該已經安裝在你的 RHEL 系統中了，儘管它可能沒有在運行。你可以使用下面的命令來確認（firewall-config 是用户界面配置工具）：</p><pre><code># yum info firewalld firewall-config
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-FirewallD-Information.png" alt="檢查 FirewallD 的信息"></p><p><em>檢查 FirewallD 的信息</em></p><p>以及，</p><pre><code># systemctl status -l firewalld.service
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-FirewallD-Status.png" alt="檢查 FirewallD 的狀態"></p><p><em>檢查 FirewallD 的狀態</em></p><p>另一方面， iptables 服務在默認情況下沒有被包含在 RHEL 系統中，但可以被安裝上。</p><pre><code># yum update &amp;&amp; yum install iptables-services
</code></pre><p>這兩個守護進程都可以使用常規的 systemd 命令來在開機時被啓動和開啓：</p><pre><code># systemctl start firewalld.service | iptables-service.service
# systemctl enable firewalld.service | iptables-service.service
</code></pre>`,19)),t("p",null,[e[1]||(e[1]=l("另外，請閲讀：",-1)),r(p,{href:"https://linux.cn/article-5926-1.html"},{default:i(()=>[...e[0]||(e[0]=[l("管理 Systemd 服務的實用命令",-1)])]),_:1})]),e[33]||(e[33]=a(`<p>至於配置文件， iptables 服務使用 <code>/etc/sysconfig/iptables</code> 文件（假如這個軟件包在你的系統中沒有被安裝，則這個文件將不存在）。在一個被用作集羣節點的 RHEL 7 機子上，這個文件看起來是這樣：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Iptables-Rules.png" alt="Iptables 防火牆配置文件"></p><p><em>Iptables 防火牆配置文件</em></p><p>而 firewalld 則在兩個目錄中存儲它的配置文件，即 <code>/usr/lib/firewalld</code> 和 <code>/etc/firewalld</code>：</p><pre><code># ls /usr/lib/firewalld /etc/firewalld
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Firewalld-configuration.png" alt="FirewallD 的配置文件"></p><p><em>FirewallD 的配置文件</em></p><p>在這篇文章中後面，我們將進一步查看這些配置文件，在那之後，我們將在這兩個地方添加一些規則。現在，是時候提醒你了，你總可以使用下面的命令來找到更多有關這兩個工具的信息。</p><pre><code># man firewalld.conf
# man firewall-cmd
# man iptables
</code></pre>`,9)),t("p",null,[e[3]||(e[3]=l("除了這些，記得查看一下當前系列的第一篇 ",-1)),r(p,{href:"https://linux.cn/article-6133-1.html"},{default:i(()=>[...e[2]||(e[2]=[l("RHCSA 系列（一）: 回顧基礎命令及系統文檔",-1)])]),_:1}),e[4]||(e[4]=l("，在其中我描述了幾種渠道來得到安裝在你的 RHEL 7 系統上的軟件包的信息。",-1))]),e[34]||(e[34]=t("h3",{id:"使用-iptables-來控制網絡流量",tabindex:"-1"},[l("使用 Iptables 來控制網絡流量 "),t("a",{class:"header-anchor",href:"#使用-iptables-來控制網絡流量","aria-label":"Permalink to “使用 Iptables 來控制網絡流量”"},"​")],-1)),t("p",null,[e[6]||(e[6]=l("在進一步深入之前，或許你需要參考 Linux 基金會認證工程師（Linux Foundation Certified Engineer,LFCE） 系列中的 ",-1)),r(p,{href:"http://www.tecmint.com/configure-iptables-firewall/"},{default:i(()=>[...e[5]||(e[5]=[l("配置 Iptables 防火牆 – Part 8",-1)])]),_:1}),e[7]||(e[7]=l(" 來複習你腦中有關 iptables 的知識。",-1))]),e[35]||(e[35]=a(`<p><strong>例 1：同時允許流入和流出的網絡流量</strong></p><p>TCP 端口 80 和 443 是 Apache web 服務器使用的用來處理常規（HTTP）和安全（HTTPS）網絡流量的默認端口。你可以像下面這樣在 enp0s3 接口上允許流入和流出網絡流量通過這兩個端口：</p><pre><code># iptables -A INPUT -i enp0s3 -p tcp --dport 80 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A OUTPUT -o enp0s3 -p tcp --sport 80 -m state --state ESTABLISHED -j ACCEPT
# iptables -A INPUT -i enp0s3 -p tcp --dport 443 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A OUTPUT -o enp0s3 -p tcp --sport 443 -m state --state ESTABLISHED -j ACCEPT
</code></pre><p><strong>例 2：從某個特定網絡中阻擋所有（或某些）流入連接</strong></p><p>或許有時你需要阻擋來自於某個特定網絡的所有（或某些）類型的來源流量，比方説 192.168.1.0/24：</p><pre><code># iptables -I INPUT -s 192.168.1.0/24 -j DROP
</code></pre><p>上面的命令將丟掉所有來自 192.168.1.0/24 網絡的網絡包，而</p><pre><code># iptables -A INPUT -s 192.168.1.0/24 --dport 22 -j ACCEPT
</code></pre><p>將只允許通過端口 22 的流入流量。</p><p><strong>例 3：將流入流量重定向到另一個目的地</strong></p><p>假如你不僅使用你的 RHEL 7 機子來作為一個軟件防火牆，而且還將它作為一個硬件防火牆，使得它位於兩個不同的網絡之間，那麼在你的系統上 IP 轉發一定已經被開啓了。假如沒有開啓，你需要編輯 <code>/etc/sysctl.conf</code> 文件並將 <code>net.ipv4.ip_forward</code> 的值設為 1，即：</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p>接着保存更改，關閉你的文本編輯器，並最終運行下面的命令來應用更改：</p><pre><code># sysctl -p /etc/sysctl.conf
</code></pre><p>例如，你可能在一個內部的機子上安裝了一個打印機，它的 IP 地址為 192.168.0.10，CUPS 服務在端口 631 上進行監聽（同時在你的打印服務器和你的防火牆上）。為了從防火牆另一邊的客户端傳遞打印請求，你應該添加下面的 iptables 規則：</p><pre><code># iptables -t nat -A PREROUTING -i enp0s3 -p tcp --dport 631 -j DNAT --to 192.168.0.10:631
</code></pre><p>請記住 iptables 會逐條地讀取它的規則，所以請確保默認的策略或後面的規則不會重載上面例子中那些規則。</p><h3 id="firewalld-入門" tabindex="-1">FirewallD 入門 <a class="header-anchor" href="#firewalld-入門" aria-label="Permalink to “FirewallD 入門”">​</a></h3>`,18)),t("p",null,[e[9]||(e[9]=l("firewalld 引入的一個變化是區域（zone） （注：翻譯參考了 ",-1)),r(p,{href:"https://fedoraproject.org/wiki/FirewallD/zh-cn"},{default:i(()=>[...e[8]||(e[8]=[l("https://fedoraproject.org/wiki/FirewallD/zh-cn",-1)])]),_:1}),e[10]||(e[10]=l(" ）。這個概念允許將網路劃分為擁有不同信任級別的區域，由用户決定將設備和流量放置到哪個區域。",-1))]),e[36]||(e[36]=t("p",null,"要獲取活動的區域，使用：",-1)),e[37]||(e[37]=t("pre",null,[t("code",null,`# firewall-cmd --get-active-zones
`)],-1)),e[38]||(e[38]=t("p",null,"在下面的例子中，public 區域是激活的，並且 enp0s3 接口被自動地分配到了這個區域。要查看有關一個特定區域的所有信息，可使用：",-1)),e[39]||(e[39]=t("pre",null,[t("code",null,`# firewall-cmd --zone=public --list-all
`)],-1)),e[40]||(e[40]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/05/View-FirewallD-Zones.png",alt:"列出所有的 Firewalld 區域"})],-1)),e[41]||(e[41]=t("p",null,[t("em",null,"列出所有的 Firewalld 區域")],-1)),t("p",null,[e[12]||(e[12]=l("由於你可以在 ",-1)),r(p,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Security_Guide/sec-Using_Firewalls.html"},{default:i(()=>[...e[11]||(e[11]=[l("RHEL 7 安全指南",-1)])]),_:1}),e[13]||(e[13]=l(" 中閲讀到更多有關區域的知識，這裏我們將僅列出一些特別的例子。",-1))]),e[42]||(e[42]=a(`<p><strong>例 4：允許服務通過防火牆</strong></p><p>要獲取受支持的服務的列表，可以使用：</p><pre><code># firewall-cmd --get-services
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/List-All-Supported-Services.png" alt="列出所有受支持的服務"></p><p><em>列出所有受支持的服務</em></p><p>要立刻生效且在隨後重啓後都可以讓 http 和 https 網絡流量通過防火牆，可以這樣：</p><pre><code># firewall-cmd --zone=MyZone --add-service=http
# firewall-cmd --zone=MyZone --permanent --add-service=http
# firewall-cmd --zone=MyZone --add-service=https
# firewall-cmd --zone=MyZone --permanent --add-service=https
# firewall-cmd --reload
</code></pre><p>假如 <code>-–zone</code> 被忽略，則使用默認的區域（你可以使用 <code>firewall-cmd –get-default-zone</code>來查看）。</p><p>若要移除這些規則，可以在上面的命令中將 <code>add</code> 替換為 <code>remove</code>。</p><p><strong>例 5：IP 轉發或端口轉發</strong></p><p>首先，你需要查看在目標區域中，偽裝（masquerading）是否被開啓：</p><pre><code># firewall-cmd --zone=MyZone --query-masquerade
</code></pre><p>在下面的圖片中，我們可以看到對於外部區域，偽裝已被開啓，但對於公用區域則沒有：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-masquerading.png" alt="在 firewalld 中查看偽裝狀態"></p><p><em>查看偽裝狀態</em></p><p>你可以為公共區域開啓偽裝：</p><pre><code># firewall-cmd --zone=public --add-masquerade
</code></pre><p>或者在外部區域中使用偽裝。下面是使用 firewalld 來重複例 3 中的任務所需的命令：</p><pre><code># firewall-cmd --zone=external --add-forward-port=port=631:proto=tcp:toport=631:toaddr=192.168.0.10
</code></pre><p>不要忘了重新加載防火牆。</p>`,20)),t("p",null,[e[15]||(e[15]=l("在 RHCSA 系列的 ",-1)),r(p,{href:"https://linux.cn/article-6286-1.html"},{default:i(()=>[...e[14]||(e[14]=[l("第九部分",-1)])]),_:1}),e[16]||(e[16]=l(" 你可以找到更深入的例子，在那篇文章中我們解釋瞭如何允許或禁用通常被 web 服務器和 ftp 服務器使用的端口，以及在針對這兩個服務所使用的默認端口被改變時，如何更改相應的規則。另外，你或許想參考 firewalld 的 wiki 來查看更深入的例子。",-1))]),t("ul",null,[t("li",null,[e[18]||(e[18]=l("延伸閲讀： ",-1)),r(p,{href:"http://www.tecmint.com/firewalld-rules-for-centos-7/"},{default:i(()=>[...e[17]||(e[17]=[l("在 RHEL 7 中配置防火牆的幾個實用的 firewalld 例子",-1)])]),_:1})])]),e[43]||(e[43]=t("h3",{id:"總結",tabindex:"-1"},[l("總結 "),t("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),e[44]||(e[44]=t("p",null,"在這篇文章中，我們已經解釋了防火牆是什麼，介紹了在 RHEL 7 中用來實現防火牆的幾個可用的服務，並提供了可以幫助你入門防火牆的幾個例子。假如你有任何的評論，建議或問題，請隨意使用下面的評論框來讓我們知曉。這裏就事先感謝了！",-1)),e[45]||(e[45]=t("hr",null,null,-1)),t("p",null,[e[20]||(e[20]=l("via: ",-1)),r(p,{href:"http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/"},{default:i(()=>[...e[19]||(e[19]=[l("http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/",-1)])]),_:1})]),t("p",null,[e[24]||(e[24]=l("作者：",-1)),r(p,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...e[21]||(e[21]=[l("Gabriel Cánepa",-1)])]),_:1}),e[25]||(e[25]=l(" 譯者：",-1)),r(p,{href:"https://github.com/FSSlc"},{default:i(()=>[...e[22]||(e[22]=[l("FSSlc",-1)])]),_:1}),e[26]||(e[26]=l(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:i(()=>[...e[23]||(e[23]=[l("wxy",-1)])]),_:1})]),t("p",null,[e[29]||(e[29]=l("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[27]||(e[27]=[l("LCTT",-1)])]),_:1}),e[30]||(e[30]=l(" 原創翻譯，",-1)),r(p,{href:"https://linux.cn/"},{default:i(()=>[...e[28]||(e[28]=[l("Linux中國",-1)])]),_:1}),e[31]||(e[31]=l(" 榮譽推出",-1))])])}const c=n(w,[["render",f]]);export{A as __pageData,c as default};
